/**
 * Shared response policy for Pages Functions and HTML documents.
 * Cloudflare Pages `_headers` rules are not applied to responses generated by
 * Pages Functions, so API and SSE routes need their own response headers.
 */
const NO_STORE = 'no-store, no-cache, must-revalidate, max-age=0';
const BASE_HEADERS = [
  ['X-Content-Type-Options', 'nosniff'],
  ['Referrer-Policy', 'strict-origin-when-cross-origin'],
  ['X-Frame-Options', 'DENY'],
  ['Cross-Origin-Opener-Policy', 'same-origin'],
  ['Cross-Origin-Resource-Policy', 'same-origin'],
];

export async function onRequest(context) {
  const response = await context.next();
  const type = (response.headers.get('content-type') || '').toLowerCase();
  const pathname = new URL(context.request.url).pathname;
  const isApi = pathname.startsWith('/api/');
  const isHtml = type.includes('text/html');
  if (!isApi && !isHtml) return response;

  const headers = new Headers(response.headers);
  for (const [name, value] of BASE_HEADERS) {
    if (!headers.has(name)) headers.set(name, value);
  }
  if (new URL(context.request.url).protocol === 'https:' && !headers.has('Strict-Transport-Security')) {
    headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  }

  if (isApi) {
    headers.set('Cache-Control', 'no-store');
    headers.set('CDN-Cache-Control', 'no-store');
    headers.set('X-Robots-Tag', 'noindex');
    if (!headers.has('Content-Security-Policy')) {
      headers.set('Content-Security-Policy', "default-src 'none'; base-uri 'none'; frame-ancestors 'none'");
    }
  }

  if (isHtml) {
    headers.set('Cache-Control', NO_STORE);
    headers.set('CDN-Cache-Control', 'no-store');
    headers.set('Pragma', 'no-cache');
    headers.set('X-Veridellindo-Page', 'function');
  }

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}
